insert into slot (key, name, description, max_items, size_spec, payload_schema, sort_order) values ('announcement_bar', 'Announcement bar', 'Thin rotating bar above the header on every page.', 5, 'Text up to 140 characters, CTA up to 40; no images.', '{"$schema": "https://json-schema.org/draft/2020-12/schema", "type": "object", "additionalProperties": false, "required": ["tone", "icon", "text", "cta", "href"], "properties": {"tone": {"type": "string", "enum": ["ink", "gold", "green", "sand"]}, "icon": {"type": "string", "minLength": 1, "maxLength": 60}, "text": {"type": "string", "minLength": 1, "maxLength": 140}, "cta": {"type": "string", "minLength": 1, "maxLength": 40}, "href": {"type": "string", "minLength": 1, "maxLength": 300, "pattern": "^(/|https://)"}}}'::jsonb, 0);
insert into slot (key, name, description, max_items, size_spec, payload_schema, sort_order) values ('hero_carousel', 'Hero carousel', 'Full-width home carousel; rotates every 7 seconds.', 6, 'Image 1920x600 desktop and 750x900 mobile, WebP/AVIF, at most 300 KB; title up to 60 characters.', '{"$schema": "https://json-schema.org/draft/2020-12/schema", "type": "object", "additionalProperties": false, "required": ["theme", "kicker", "title", "sub", "cta", "href", "label"], "properties": {"theme": {"type": "string", "enum": ["ink", "gold", "green", "sand"]}, "kicker": {"type": "string", "minLength": 1, "maxLength": 40}, "title": {"type": "string", "minLength": 1, "maxLength": 60}, "sub": {"type": "string", "minLength": 1, "maxLength": 160}, "cta": {"type": "string", "minLength": 1, "maxLength": 40}, "href": {"type": "string", "minLength": 1, "maxLength": 300, "pattern": "^(/|https://)"}, "label": {"type": "string", "enum": ["AfroTransact", "Sponsored"]}, "imageUrl": {"type": ["string", "null"], "maxLength": 500, "pattern": "^https://"}, "imageAlt": {"type": "string", "minLength": 0, "maxLength": 160}}}'::jsonb, 10);
insert into slot (key, name, description, max_items, size_spec, payload_schema, sort_order) values ('home_tiles', 'Home tiles', 'Quad tiles under the hero (up to four linked cells each).', 8, 'Cell images 300x300, WebP/AVIF, at most 80 KB each.', '{"$schema": "https://json-schema.org/draft/2020-12/schema", "type": "object", "additionalProperties": false, "required": ["title", "cta", "href", "cells"], "properties": {"title": {"type": "string", "minLength": 1, "maxLength": 60}, "cta": {"type": "string", "minLength": 1, "maxLength": 40}, "href": {"type": "string", "minLength": 1, "maxLength": 300, "pattern": "^(/|https://)"}, "cells": {"type": "array", "minItems": 1, "maxItems": 4, "items": {"$schema": "https://json-schema.org/draft/2020-12/schema", "type": "object", "additionalProperties": false, "required": ["label", "href"], "properties": {"label": {"type": "string", "minLength": 1, "maxLength": 40}, "href": {"type": "string", "minLength": 1, "maxLength": 300, "pattern": "^(/|https://)"}, "imageUrl": {"type": ["string", "null"], "maxLength": 500, "pattern": "^https://"}}}}}}'::jsonb, 20);
insert into slot (key, name, description, max_items, size_spec, payload_schema, sort_order) values ('home_product_row', 'Home product row', 'A product rail on the home page filled from a search query or a SKU list.', 6, 'No creative; products render from the catalogue.', '{"$schema": "https://json-schema.org/draft/2020-12/schema", "type": "object", "additionalProperties": false, "required": ["title", "href"], "properties": {"title": {"type": "string", "minLength": 1, "maxLength": 60}, "href": {"type": "string", "minLength": 1, "maxLength": 300, "pattern": "^(/|https://)"}, "query": {"type": "string", "minLength": 1, "maxLength": 200}, "skus": {"type": "array", "minItems": 1, "maxItems": 24, "uniqueItems": true, "items": {"type": "string", "minLength": 1, "maxLength": 64}}}, "anyOf": [{"required": ["query"]}, {"required": ["skus"]}]}'::jsonb, 30);
insert into slot (key, name, description, max_items, size_spec, payload_schema, sort_order) values ('display_banner', 'Display banner', 'Home page display banner (first-party or sponsored).', 3, 'Image 1200x300 desktop and 750x400 mobile, at most 200 KB; always labelled when sponsored.', '{"$schema": "https://json-schema.org/draft/2020-12/schema", "type": "object", "additionalProperties": false, "required": ["position", "advertiser", "title", "sub", "cta", "href"], "properties": {"position": {"type": "string", "enum": ["home-top", "home-mid", "home-bottom"]}, "advertiser": {"type": "string", "minLength": 1, "maxLength": 120}, "title": {"type": "string", "minLength": 1, "maxLength": 80}, "sub": {"type": "string", "minLength": 1, "maxLength": 160}, "cta": {"type": "string", "minLength": 1, "maxLength": 40}, "href": {"type": "string", "minLength": 1, "maxLength": 300, "pattern": "^(/|https://)"}, "imageUrl": {"type": ["string", "null"], "maxLength": 500, "pattern": "^https://"}}}'::jsonb, 40);
insert into slot (key, name, description, max_items, size_spec, payload_schema, sort_order) values ('category_banner', 'Category banner', 'Banner at the top of a category page (target categories in targeting).', 2, 'Image 1200x240, at most 150 KB.', '{"$schema": "https://json-schema.org/draft/2020-12/schema", "type": "object", "additionalProperties": false, "required": ["title", "cta", "href"], "properties": {"title": {"type": "string", "minLength": 1, "maxLength": 80}, "sub": {"type": "string", "minLength": 1, "maxLength": 160}, "cta": {"type": "string", "minLength": 1, "maxLength": 40}, "href": {"type": "string", "minLength": 1, "maxLength": 300, "pattern": "^(/|https://)"}, "advertiser": {"type": "string", "minLength": 1, "maxLength": 120}, "imageUrl": {"type": ["string", "null"], "maxLength": 500, "pattern": "^https://"}}}'::jsonb, 50);
insert into slot (key, name, description, max_items, size_spec, payload_schema, sort_order) values ('checkout_cross_sell', 'Checkout cross-sell', 'One product rail offered on the checkout review step.', 1, 'No creative; up to 12 products.', '{"$schema": "https://json-schema.org/draft/2020-12/schema", "type": "object", "additionalProperties": false, "required": ["title", "skus"], "properties": {"title": {"type": "string", "minLength": 1, "maxLength": 60}, "skus": {"type": "array", "minItems": 1, "maxItems": 12, "uniqueItems": true, "items": {"type": "string", "minLength": 1, "maxLength": 64}}, "reason": {"type": "string", "minLength": 1, "maxLength": 120}}}'::jsonb, 60);
